import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    MOD = 10**9 + 7
    results = []

    for _ in range(T):
        try:
            S = next(iterator)
        except StopIteration:
            break

        n = len(S)
        suffixes = [S[i:] for i in range(n)]
        suffixes.sort()

        def lcp(s1, s2):
            length = min(len(s1), len(s2))
            i = 0
            while i < length and s1[i] == s2[i]:
                i += 1
            return i

        distinct_substrings_count = {}

        for i in range(n):
            current_suffix = suffixes[i]
            if i == 0:
                prev_lcp = 0
            else:
                prev_suffix = suffixes[i-1]
                prev_lcp = lcp(current_suffix, prev_suffix)

            max_len = len(current_suffix)
            new_substrings_count = max_len - prev_lcp

            if new_substrings_count > 0:
                start_len = prev_lcp + 1
                end_len = max_len

                if start_len not in distinct_substrings_count:
                    distinct_substrings_count[start_len] = 0
                distinct_substrings_count[start_len] += 1

                if end_len + 1 not in distinct_substrings_count:
                    distinct_substrings_count[end_len + 1] = 0
                distinct_substrings_count[end_len + 1] -= 1

        running_count = 0
        total_sum = 0

        for length in range(1, n + 1):
            if length in distinct_substrings_count:
                running_count = (running_count + distinct_substrings_count[length]) % MOD

            if running_count > 0:
                term = pow(length, running_count, MOD)
                total_sum = (total_sum + term) % MOD

        results.append(str(total_sum))

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
